const cfg = $('Load Clinic Config').item.json;
const ai = $json.output ?? $json;

// Config guard: refuse to run against an unconfigured clinic (prevents wrong-namespace queries)
if (!cfg.pinecone_namespace || !cfg.sheet_id) {
  throw new Error('Clinic config incomplete: pinecone_namespace or sheet_id is empty');
}

// Compute is_open_now from hours_json (local server time)
let isOpen = true;
try {
  const hours = JSON.parse(cfg.hours_json || '{}');
  const now = $now; // luxon DateTime
  const dayKey = ['sun','mon','tue','wed','thu','fri','sat'][now.weekday % 7];
  const spec = hours[dayKey];
  if (!spec || spec === 'closed') { isOpen = false; }
  else { const [o, c] = spec.split('-').map(Number); const h = now.hour; isOpen = h >= o && h < c; }
} catch (e) { isOpen = true; }

const intent = ai.intent || 'unknown';
const patient = ai.patient || {};

return { json: {
  clinic: {
    clinic_id: cfg.clinic_id, clinic_name: cfg.clinic_name, address: cfg.address,
    staff_email: cfg.staff_email, staff_phone: cfg.staff_phone, twilio_from: cfg.twilio_from,
    pinecone_index: cfg.pinecone_index, pinecone_namespace: cfg.pinecone_namespace,
    sheet_id: cfg.sheet_id, drive_folder_id: cfg.drive_folder_id,
    hours_json: cfg.hours_json, after_hours_message: cfg.after_hours_message,
    sms_enabled_patient: cfg.sms_enabled_patient, sms_enabled_staff: cfg.sms_enabled_staff,
    pinecone_min_score: cfg.pinecone_min_score, test_mode: cfg.test_mode, is_open_now: isOpen
  },
  session_id: cfg.sessionId,
  timestamp: $now.toISO(),
  user_message: cfg.chatInput,
  intent, confidence: ai.confidence ?? 0, urgency: ai.urgency || 'normal',
  summary: ai.summary || '', missing_fields: ai.missing_fields || [],
  next_question: ai.next_question || '',
  patient: {
    name: patient.name || '', phone: patient.phone || '', email: patient.email || '',
    patient_type: patient.patient_type || '', service: patient.service || '',
    preferred_date: patient.preferred_date || '', preferred_time: patient.preferred_time || '',
    existing_appt_datetime: patient.existing_appt_datetime || '', new_preferred_datetime: patient.new_preferred_datetime || '',
    symptoms: patient.symptoms || '', reason: patient.reason || ''
  },
  bot_response: ''
} };

const c = $json;
const clinic = c.clinic || $('Build Context').item.json.clinic;
let reply = c.bot_response || 'Thank you — our team will follow up with you.';

// After-hours expectation for actionable intents
const actionable = ['appointment_request','cancellation_request','reschedule_request','human_handoff','emergency'];
if (clinic && clinic.is_open_now === false && actionable.includes(c.intent)) {
  reply = reply + '\n\n' + (clinic.after_hours_message || '');
}

// Build the Conversations log row (consumed by M7)
return { json: {
  bot_response: reply,
  tab: 'Conversations',
  operation: 'append',
  sheet_id: clinic.sheet_id,
  timestamp: c.timestamp || $now.toISO(),
  session_id: c.session_id,
  user_message: c.user_message,
  intent: c.intent,
  confidence: c.confidence,
  urgency: c.urgency,
  patient_name: c.patient?.name || '',
  phone: c.patient?.phone || '',
  email: c.patient?.email || '',
  status: 'Logged',
  notes: (clinic.test_mode ? '[TEST] ' : '') + (c.summary || '')
} };
